def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    scores = [int(x) for x in data]
    total_sum = sum(scores)

    # If total sum is odd, we cannot split it into two equal integer sums
    if total_sum % 2 != 0:
        print("NO")
        return

    target = total_sum // 2

    # We need to find if there exists a subset of exactly 3 students whose sum equals target
    # Since n=6 is very small, we can use three nested loops to pick 3 distinct indices
    n = 6
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if scores[i] + scores[j] + scores[k] == target:
                    print("YES")
                    return

    print("NO")

if __name__ == "__main__":
    solve()

