import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    a = [int(x) for x in data]
    total = sum(a)
    if total % 2 != 0:
        print("NO")
        return
    target = total // 2
    n = 6
    for mask in range(1, 1 << n):
        if bin(mask).count('1') != 3:
            continue
        s = 0
        for i in range(n):
            if mask & (1 << i):
                s += a[i]
        if s == target:
            print("YES")
            return
    print("NO")

if __name__ == "__main__":
    solve()

